import 'package:flutter/material.dart'; import 'package:flutter_riverpod/flutter_riverpod.dart'; import 'package:go_router/go_router.dart'; import '../../../../shared/providers/auth_provider.dart'; import '../../../products/presentation/screens/my_products_screen.dart'; import '../../../surplus/presentation/screens/surplus_screen.dart'; import '../../../orders/presentation/screens/orders_screen.dart';
class FarmerDashboard extends ConsumerWidget{const FarmerDashboard({super.key});@override Widget build(BuildContext c,WidgetRef ref){final user=ref.watch(authProvider).user;return Scaffold(appBar:AppBar(title:const Text('Farmer Dashboard'),actions:[IconButton(onPressed:()async{await ref.read(authProvider.notifier).logout();if(c.mounted)c.go('/login');},icon:const Icon(Icons.logout))]),body:ListView(padding:const EdgeInsets.all(20),children:[Text('Welcome ${user?.name??'Farmer'} 👋',style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:6),const Text('Manage crops, orders and market surplus.'),const SizedBox(height:24),_tile(c,'My Crops','Add, edit and remove your products',Icons.agriculture,()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>const MyProductsScreen()))),_tile(c,'Orders','View consumer orders',Icons.receipt_long,()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>const OrdersScreen()))),_tile(c,'Surplus Monitor','See supply, demand and export activation',Icons.analytics,()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>const SurplusScreen()))),]));}}
Widget _tile(BuildContext c,String t,String s,IconData i,VoidCallback f)=>Card(child:ListTile(onTap:f,leading:CircleAvatar(child:Icon(i)),title:Text(t,style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text(s),trailing:const Icon(Icons.chevron_right)));
